/// <summary>
/// CB129 Cancellation of Open SO/PO lines
/// </summary>
internal final class METPurchCancelService extends SysOperationServiceBase
{
    METChangeReasonCode reasonCode;
    container purchLineCon;
    METPOASNResp asnReceived;

}

Method.Source:
/// <summary>
/// The process method for the back orders processing
/// </summary>
/// <param name = "_contract">The data contract object</param>
public void processOperation(METPurchCancelContract _contract)
{ 
    int i = 0;
    boolean errorAllowPurchBackOrder = false;

    reasonCode      = _contract.parmReasonCode();
    asnReceived     = _contract.parmAsnReceived();
    purchLineCon    = _contract.parmPurchLineRecords();

    [errorAllowPurchBackOrder, i] = this.cancelPurchOrderLines();

    str infoMessage = strFmt("@MET:LinesCancelled", i);

    if (errorAllowPurchBackOrder)
    {
        throw error("@MET:CancelErr" + METConstants::space + infoMessage);
    }

    info(infoMessage);
}

/// <summary>
/// Cancel PO lines
/// </summary>
/// <returns>container with false if any errors; otherwise true and the number of sales line cancelled</returns>
container cancelPurchOrderLines()
{
    Query query;
    QueryRun queryRun;
    int i = 0;
    PurchLine   purchLine;
    boolean error = false;
    METPurchLine metPurchLine;

    // Build the query
    query = this.buildQuery();

    queryRun = new QueryRun(query);

    // loop through all lines
    while (queryRun.next())
    {
        purchLine = queryRun.get(tableNum(PurchLine));

        try
        {
            setPrefix(strFmt(METConstants::CancelLinePrefix, purchLine.PurchId, purchLine.ItemId, purchLine.LineNumber));
            purchLine.selectForUpdate(true);
            purchLine.RemainPurchPhysical = 0;
            purchLine.RemainInventPhysical = 0;
            ttsbegin;
            purchLine.update();
            ttscommit;

            metPurchLine = metPurchLine::find(purchLine.RecId,true);
            if(metPurchLine)
            {
                ttsbegin;
                metPurchLine.ChangeReasonCode = reasonCode;
                metPurchLine.update();
                ttscommit;
            }

            i++;
        }
        // If any errors continue to the next backorder line to cancel
        catch (Exception::Error)
        {
            error = true;
        }
    }

    return [error, i];
}

/// <summary>
/// Build query to cancel sales lines
/// </summary>
/// <returns>Query object</returns>
Query buildQuery()
{
    QueryBuildDataSource qbdsPurchLine, qbdsMETPurchLine,qbdsMETPurchTable;

    Query query = new Query(queryStr(METPurchLineCancel));

    qbdsPurchLine = query.dataSourceTable(tableNum(PurchLine));
    qbdsMETPurchTable = query.dataSourceTable(tableNum(METPurchTable));

    qbdsMETPurchLine = query.dataSourceTable(tablenum(METPurchLine));

    QueryBuildRange qbrPurchLines = qbdsPurchLine.addRange(fieldnum(PurchLine, RecId));
    qbrPurchLines.value(con2Str(purchLineCon));

  //  if (asnReceived)
    {
        qbdsMETPurchTable.addRange(fieldNum(METPurchTable, POASNResp)).value(queryValue(asnReceived));
    }
    return query;
}
